<script setup lang="ts">
import {ref,watch,onMounted} from 'vue';
import Icon from './Icon.vue';
type Label={id:number;name:string;color:string};type Comment={id:number;body:string;author:string;created_at:string;updated_at:string};type Attachment={id:number;name:string;bytes:number};
const props=defineProps<{taskId:number;csrf:string;tab?:string}>();const emit=defineEmits(['updated','pending','working']);
const labels=ref<Label[]>([]),selected=ref<number[]>([]),comments=ref<Comment[]>([]),files=ref<Attachment[]>([]),body=ref(''),labelName=ref(''),color=ref('green'),busy=ref(false),error=ref(''),editing=ref<number|null>(null),editBody=ref('');
const confirmAction=ref<{text:string;action:()=>void}|null>(null);
watch([body,labelName,editing,editBody],()=>emit('pending',!!body.value.trim()||!!labelName.value.trim()||editing.value!==null));
async function request(path:string,method='GET',data?:unknown){const form=data instanceof FormData;const r=await fetch(path,{method,credentials:'same-origin',headers:{Accept:'application/json','X-CSRF-TOKEN':props.csrf,...(form?{}:{'Content-Type':'application/json'})},...(data===undefined?{}:{body:form?data as FormData:JSON.stringify(data)})});if(r.status===204)return null;let d;try{d=await r.json()}catch{throw Error('Сервер не принял запрос. Проверьте размер файла и соединение.')}if(!r.ok)throw Error(d.errors?Object.values(d.errors).flat().join(' '):r.status===419?'Сессия истекла. Обновите страницу после сохранения введённого текста.':d.message||'Ошибка запроса');return d}
async function load(){const [d,l]=await Promise.all([request('/tasks/'+props.taskId+'/details'),request('/labels')]);comments.value=d.comments;files.value=d.attachments;selected.value=d.task.labels.map((x:Label)=>x.id);labels.value=l;emit('updated',d.task)}
async function run(action:()=>Promise<void>){if(busy.value)return;busy.value=true;emit('working',true);error.value='';try{await action()}catch(e){error.value=e instanceof Error?e.message:'Ошибка соединения'}finally{busy.value=false;emit('working',false)}}
onMounted(()=>run(load));
function toggleLabel(id:number){const ids=selected.value.includes(id)?selected.value.filter(x=>x!==id):[...selected.value,id];run(async()=>{await request('/tasks/'+props.taskId+'/labels','PUT',{ids});await load()})}
function createLabel(){run(async()=>{await request('/labels','POST',{name:labelName.value.trim(),color:color.value});labelName.value='';await load()})}
function addComment(){run(async()=>{await request('/tasks/'+props.taskId+'/comments','POST',{body:body.value.trim()});body.value='';await load()})}
function saveComment(id:number){run(async()=>{await request('/tasks/'+props.taskId+'/comments/'+id,'PATCH',{body:editBody.value.trim()});editing.value=null;editBody.value='';await load()})}
function ask(text:string,action:()=>void){confirmAction.value={text,action}}
function accept(){const action=confirmAction.value?.action;confirmAction.value=null;action?.()}
function deleteComment(id:number){ask('Удалить этот комментарий?',()=>run(async()=>{await request('/tasks/'+props.taskId+'/comments/'+id,'DELETE');if(editing.value===id){editing.value=null;editBody.value=''}await load()}))}
function upload(e:Event){const el=e.target as HTMLInputElement;const file=el.files?.[0];if(!file)return;if(file.size>10*1024*1024){error.value='Максимальный размер файла — 10 МБ.';el.value='';return}const form=new FormData();form.append('file',file);run(async()=>{await request('/tasks/'+props.taskId+'/attachments','POST',form);el.value='';await load()})}
function deleteFile(id:number){ask('Удалить это вложение?',()=>run(async()=>{await request('/tasks/'+props.taskId+'/attachments/'+id,'DELETE');await load()}))}
const date=(v:string)=>new Date(v.endsWith('Z')?v:v.replace(' ','T')+'Z').toLocaleString('ru-RU');
</script>
<template><section v-show="!tab||['labels','files','comments'].includes(tab)" class="extras" :aria-busy="busy"><p class="muted extras-note">Метки, файлы и комментарии сохраняются отдельно от полей задачи.</p><p v-if="error" class="error" role="alert">{{error}}</p><div v-if="confirmAction" class="extras-confirm" role="alert"><p>{{confirmAction.text}}</p><button @click="confirmAction=null">Отмена</button> <button class="danger" @click="accept">Удалить</button></div>
<div v-show="!tab||tab==='labels'"><h3>Метки</h3><div class="label-options"><button v-for="l in labels" :key="l.id" :class="['label-badge',l.color,{chosen:selected.includes(l.id)}]" :aria-pressed="selected.includes(l.id)" :disabled="busy" @click="toggleLabel(l.id)">{{selected.includes(l.id)?'✓ ':''}}{{l.name}}</button><span v-if="!labels.length" class="muted">Пока нет меток</span></div><form class="label-create" @submit.prevent="createLabel"><input v-model="labelName" required maxlength="40" placeholder="Новая метка" aria-label="Название метки" :disabled="busy"><select v-model="color" aria-label="Цвет метки" :disabled="busy"><option value="green">Зелёный</option><option value="blue">Синий</option><option value="purple">Фиолетовый</option><option value="orange">Оранжевый</option><option value="red">Красный</option><option value="gray">Серый</option></select><button :disabled="busy">＋</button></form>
</div><div v-show="!tab||tab==='files'"><h3><Icon name="attachment"/> Файлы · {{files.length}}</h3><p class="muted extras-note">До 10 МБ: документы, PDF, изображения, TXT/CSV и ZIP.</p><input type="file" :disabled="busy" @change="upload" accept=".pdf,.txt,.csv,.jpg,.jpeg,.png,.webp,.zip,.doc,.docx,.xls,.xlsx" aria-label="Прикрепить файл"><div v-for="f in files" :key="f.id" class="attachment-row"><a :href="'/tasks/'+taskId+'/attachments/'+f.id" download>{{f.name}}</a><small>{{Math.ceil(f.bytes/1024)}} КБ</small><button :disabled="busy" @click="deleteFile(f.id)" aria-label="Удалить вложение">×</button></div>
</div><div v-show="!tab||tab==='comments'"><h3><Icon name="comment"/> Комментарии · {{comments.length}}</h3><article v-for="c in comments" :key="c.id" class="comment"><small><b>{{c.author}}</b> · {{date(c.created_at)}} <span v-if="c.updated_at!==c.created_at">· изменён</span></small><template v-if="editing===c.id"><textarea v-model="editBody" maxlength="10000" :disabled="busy" aria-label="Изменить комментарий"></textarea><button :disabled="busy||!editBody.trim()" @click="saveComment(c.id)">Сохранить</button><button class="link" @click="editing=null;editBody=''" :disabled="busy">Отмена</button></template><template v-else><p>{{c.body}}</p><button class="link" :disabled="busy||editing!==null" @click="editing=c.id;editBody=c.body">Изменить</button><button class="link danger" :disabled="busy" @click="deleteComment(c.id)">Удалить</button></template></article><form @submit.prevent="addComment"><label>Новый комментарий<textarea v-model="body" required maxlength="10000" rows="3" :disabled="busy" placeholder="Запишите мысль или результат работы…"></textarea></label><button class="wide" :disabled="busy||!body.trim()">{{busy?'Подождите…':'Добавить комментарий'}}</button></form></div></section></template>
